default.nix
{
  bsv,
  build,
  host ? build,
  target,
}:
let
  lib = bsv.lib;
  repos = import ../repositories.nix;
  src = repos.binutils;
in
lib.bwrapDerivation {
  name = "${build.system}.${host.name}.andes.${target.name}.binutils";

  root = [
    build.stdenv
    build.bison
    build.flex
    build.m4
    build.perl
    build."${host.name}-toolchain"
    host.zlib
  ];

  env = {
    inherit src;

    inherit (build) PATH;
    inherit (host)
      CC
      CXX
      CFLAGS
      CXXFLAGS
      LDFLAGS
      ;
  };

  builder = lib.configureMake rec {
    preConfigure = ''
      export CPPFLAGS="-DCOPILOT_GAS_KEY=$(cat ${repos.copilot-gas-key}/key)"

