=== default.nix ===
let
  bsv = {
    lib = import ./lib/default.nix;

    legacyPackages.aarch64-darwin = import ./pkgs/aarch64-darwin.nix;

    legacyPackages.aarch64-linux = import ./pkgs/aarch64-linux.nix;

    legacyPackages.x86_64-linux = import ./pkgs/x86_64-linux.nix;

    legacyPackages.x86_64-windows = import ./pkgs/x86_64-windows/default.nix;

    apps.x86_64-linux.qemu-system-n45 = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu.runners.qemu-system-n45}";
      meta.description = "QEMU system mode runner on Andes N45 for bare-metal ELF executables.";
    };

    apps.x86_64-linux.qemu-system-nx45 = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu.runners.qemu-system-nx45}";
      meta.description = "QEMU system mode runner on Andes NX45 for bare-metal ELF executables.";
    };

    apps.x86_64-linux.sid-n25f = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu.runners.sid-n25f}";
      meta.description = "SID runner on Andes N25F for bare-metal ELF executables.";
    };

    apps.x86_64-linux.sid-nx25f = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu.runners.sid-nx25f}";
      meta.description = "SID runner on Andes NX25F for bare-metal ELF executables.";
    };

    apps.x86_64-linux.sid-n45 = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu.runners.sid-n45}";
      meta.description = "SID runner on Andes N45 for bare-metal ELF executables.";
    };

    apps.x86_64-linux.sid-nx45 = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu.runners.sid-nx45}";
      meta.description = "SID runner on Andes NX45 for bare-metal ELF executables.";
    };

    formatter.x86_64-linux = bsv.legacyPackages.x86_64-linux.nixfmt-tree;

    apps.x86_64-linux.nix = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.nix}/bin/nix";
      meta.description = "Nix package manager";
    };

    apps.x86_64-linux.nixfmt-tree = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.nixfmt-tree}/bin/treefmt";
      meta.description = "Nix formatter with treefmt";
    };

    apps.x86_64-linux.nixd = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.nixd}/bin/nixd";
      meta.description = "Nix language server";
    };

    apps.x86_64-linux.mdbook = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.mdbook}/bin/mdbook";
      meta.description = "Create book from markdown";
    };

    apps.x86_64-linux.mdbook-admonish = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.mdbook-admonish}/bin/mdbook-admonish";
      meta.description = "Preprocessor for mdbook to add Material Design admonishments";
    };

    apps.x86_64-linux.mdbook-cmds = {
      type = "app";
      program = "${bsv.legacyPackages.x86_64-linux.mdbook-cmdrun}/bin/mdbook-cmdrun";
      meta.description = "Preprocessor for mdbook to run arbitrary commands";
    };

    checks.x86_64-linux.default = bsv.lib.allDerivations {
      name = "default-check";
      drvs = builtins.map import (builtins.attrNames (builtins.getContext (builtins.toJSON bsv.reports)));
    };

    logomark = import ./logomark.nix;

    mirror = import ./hashed-mirror.nix;

    reports.andes = bsv.lib.normalizeReport (import ./reports/andes.nix);

    reports.eembc = bsv.lib.normalizeReport (import ./reports/eembc.nix);

    reports.hello = bsv.lib.normalizeReport (import ./reports/hello.nix);

    reports.host = bsv.lib.normalizeReport (import ./reports/host.nix);

    reports.plumhall = bsv.lib.normalizeReport (import ./reports/plumhall.nix);

    reports.tests = bsv.lib.normalizeReport (import ./reports/tests.nix);
  };
in
bsv

