  bsv = import ../default.nix;
  lib = bsv.lib;

  system = "x86_64-linux";

  ndsv5-hosts = builtins.mapAttrs (
    _: config:
    import ./andes/ndsv5-packages.nix {
      inherit bsv;
      build = bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu;
      config = config;
    }
  ) (import ./andes/toolchain-configs.nix);
in
{
