{
  bsv,
  build,
  target,
}:
let
  lib = bsv.lib;
  host = build;

  src = (import ../repositories.nix).gcc;

  elfConfigureFlags = [
    "--enable-Os-default-execit=yes"
  ];

  linuxConfigureFlags = [
  ];
in
lib.bwrapDerivation {
  name = "${build.system}.${host.name}.andes.${target.name}.gcc-stage1";

  root = [
    build.stdenv
    build.andes."${target.name}".binutils
    build.bison
    build.flex
    build.m4
    host.gmp
    host.isl
    host.mpc
    host.mpfr
  ];

  env = {
    inherit src;

    inherit (build) PATH;
    inherit (host)
      CC
      CXX
      CFLAGS
      CXXFLAGS
      LDFLAGS
      ;
  };

  builder = lib.configureMake {
    configureFlags =
      builtins.sort builtins.lessThan
      <|
        [
          "--build=${build.triple}"
          "--disable-nls"
          "--disable-shared"
          "--disable-threads"
          "--disable-werror"
          "--enable-checking=release"
          "--enable-gp-insn-relax-default=yes"
          "--enable-languages=c"
          "--enable-tls"
          "--host=${host.triple}"
          "--libdir=${host.libdir}"
          "--prefix=${host.prefix}"
          "--target=${target.triple}"
          "--with-abi=${target.config.abi}"
          "--with-arch=${target.config.arch}"
          "--with-newlib"
          "--with-pkgversion=${src.rev or "unknown"}"
          "--with-sysroot=${host.andes.${target.name}.sysroot}"
          "--with-tune=${target.config.tune}"
          "--without-headers"
        ]
        ++ (
          if target.config.multilib-list != "" then
            [
              "--enable-multilib=yes"
              "--with-multilib-list=${target.config.multilib-list}"
            ]
          else
            [
              "--disable-multilib"
            ]
        )
        ++ (if target.config.libc == "mculib" then [ "--with-libc=mculib" ] else [ ])
        ++ (if target.triple.os == "linux" then linuxConfigureFlags else elfConfigureFlags);

    makeFlags = [
      "all-gcc"
      "all-target-libgcc"
    ];

    installCommand = "make";

    installFlags = [
      "install-gcc"
      "install-target-libgcc"
    ];

    postInstall = ''
      rm --recursive --force --verbose $out/${host.prefix}/share/{man,info}
    '';
  };

  unsafeDiscardReferences.out = true;

  system = build.system;
}

