/**
  Build a ndsv5 toolchain.

  Both building a native-cross toolchain (build == host) or a
  canadian-cross toolchain (build != host) are supported.
*/

{
  bsv,
  build,
  host ? build,
  target,
}:
assert builtins.isString target.config.abi;
assert builtins.isString target.config.tune;
assert builtins.isString target.config.libc;
let
  lib = bsv.lib;

  CROSS_COMPILE = "${toolchain}/${host.prefix}/bin/${target.triple}-";

  sysroot =
    {
      elf = "${host.prefix}/${target.triple}";
      linux = "${host.prefix}/${target.triple}/sys-root";
    }
    .${target.triple.os};

  relocateTargetLibrary =
    {
      name,
      drv,
    }:
    if build.prefix != host.prefix then
      lib.bwrapDerivation {
        inherit name;

        root = [ build.stdenv-nocc ];

        env = {
          inherit (build) PATH;
        };

        builder = lib.bashBuilder ''
          mkdir --parents $out/${host.prefix}
          cp --archive \
            ${drv}/${build.prefix}/${target.triple} \
            $out/${host.prefix}
        '';

        system = build.system;
      }
    else
      drv;

  binutils = import ./binutils/default.nix {
    inherit bsv;
    inherit build;
    inherit host;
    inherit target;
  };

  gdb = import ./gdb/default.nix {
    inherit bsv;
    inherit build;
    inherit host;
    inherit target;
  };

  gcc-stage1 = import ./gcc-stage1/default.nix {
    inherit bsv;
    inherit build;
    inherit target;
  };

  ide-gen-configs = import ./ide-gen-configs/default.nix {
    inherit
      bsv
      build
      host
      target
      ;
  };

  installer = import ./installer/default.nix {
    inherit
      bsv
      build
      host
      target
      ;
  };

  linux-headers = lib.bwrapDerivation {
    name = "${build.system}.${host.name}.andes.${target.name}.linux-headers";

    root = [
      build.stdenv-nocc
    ];

    env = {
      inherit (build) PATH;
    };

    builder = lib.bashBuilder ''
      mkdir --parents $out/${target.prefix}/include
      cp --archive --verbose ${build.andes.linux-headers}/. $out/${target.prefix}/include
    '';

    system = build.system;
  };

  libc = relocateTargetLibrary {
    name = "${build.system}.${host.name}.andes.${target.name}.libc";
    drv = target.libc;
  };

  gcc-stage2 = import ./gcc-stage2/default.nix {
    inherit
      bsv
      build
      host
      target
      ;
  };

  llvm-project = host.andes.llvm-project;

  hasClangMultilibYaml = target.triple.os == "elf" && target.config.multilib-list != "";

  clang-multilib-yaml =
    if hasClangMultilibYaml then
      import ./clang-multilib-yaml/default.nix {
        inherit bsv build host;
        target-name = target.name;
        inherit (target.config) multilib-list;
      }
    else
      null;

  gcc-wrapper = import ./compiler-wrapper {
    inherit
      bsv
      build
      host
      target
      ;
    compiler-wrapper = "gcc-wrapper";
    ld = "bfd";
  };

  clang-wrapper = import ./compiler-wrapper {
    inherit
      bsv
      build
      host
      target
      ;
    compiler-wrapper = "clang-wrapper";
    ld = "lld";
  };

  libcxx =
    if target.triple.os == "linux" then
      relocateTargetLibrary {
        name = "${build.system}.${host.name}.andes.${target.name}.libcxx";
        drv = target.libcxx;
      }
    else
      null;

  compiler-rt-stage2 =
    if target.triple.os == "linux" then
      relocateTargetLibrary {
        name = "${build.system}.${host.name}.andes.${target.name}.compiler-rt-stage2";
        drv = target.compiler-rt-stage2;
      }
    else
      null;

  components = [
    binutils
    gdb
    gcc-stage2
    libc
    llvm-project
    gcc-wrapper
    clang-wrapper
    host.andes.python
  ]
  ++ (if hasClangMultilibYaml then [ clang-multilib-yaml ] else [ ])
  ++ (
    if target.triple.os == "linux" then
      [
        libcxx
        compiler-rt-stage2
      ]
    else
      [ ]
  );

  toolchain = lib.bwrapDerivation {
    name = "${build.system}.${host.name}.andes.${target.name}";

    root = [ build.stdenv-nocc ];

    env = {
      inherit (build) PATH;
    };

    builder =
      lib.bashBuilder
      <| lib.formatCommands [
        ''
          mkdir --parents "$out"
          for d in ${builtins.concatStringsSep " " components}; do
            cp --recursive --verbose "$d"/. "$out"
            chmod --recursive u+w "$out"

            # Rename riscv[32|64]-unknown-elf-[cpp|gcc|g++] to riscv[32|64]-unknown-elf-[cpp|gcc|g++].gnu
            # to allow the wrapper can call it by this name.
            if [[ $d == ${gcc-stage2} ]]; then
              mv --verbose $out/${host.prefix}/bin/${target.triple}-cpp{,.gnu}${host.EXEEXT}
              mv --verbose $out/${host.prefix}/bin/${target.triple}-gcc{,.gnu}${host.EXEEXT}
              mv --verbose $out/${host.prefix}/bin/${target.triple}-g++{,.gnu}${host.EXEEXT}
            fi
          done
        ''

        ''
          rm --force $out/${host.prefix}/bin/${target.triple}-run${host.EXEEXT}
        ''

        ''
          ln --symbolic --force lld${host.EXEEXT} $out/${host.prefix}/bin/${target.triple}-ld.lld${host.EXEEXT}
          ln --symbolic --force ../../bin/lld${host.EXEEXT} $out/${host.prefix}/${target.triple}/bin/ld.lld
        ''

        # Add the symlinks from ${target-triple-alias} to ${target-triple}.
        ''
          for f in $out/${host.prefix}/bin/${target.triple}*; do
            ln --symbolic --force $(basename $f) ''${f/${target.triple}/${target.config.target-triple-alias}}
          done
          ln --symbolic --force ${target.triple} $out/${host.prefix}/${target.config.target-triple-alias}
        ''

        # HACK: On RHEL-based 64-bit Linux, gcc's libdir is `${exec-prefix}/lib64.
        # However, riscv32-*-clang still looks for gcc-toolchain under
        # `${exec-prefix}/lib`, so we create a compatibility symlink.
        #
        # Ref: https://gitea.andestech.com/RD-SW/bsv/issues/26
        (
          if host.triple == "x86_64-pc-linux-gnu" && host.libdirSuffix != "" then
            ''
              mkdir --parents $out/${host.prefix}/lib
              ln --symbolic --force ../lib${host.libdirSuffix}/gcc $out/${host.prefix}/lib/gcc
            ''
          else
            ""
        )

        # Copy target libraries from build's gcc-stage2 when in canadian-cross mode.
        (
          if build.triple != host.triple then
            let
              build-gcc-stage2 = build.andes."${target.name}".gcc-stage2;
              gccDir = "gcc/${target.triple}/$(${build-gcc-stage2}/${build.prefix}/bin/${target.triple}-gcc -dumpversion)";
            in
            ''
              cp --recursive --verbose ${build-gcc-stage2}/${build.prefix}/${target.triple}/. $out/${host.prefix}/${target.triple}
              cp --recursive --verbose ${build-gcc-stage2}/${build.prefix}/lib64/${gccDir}/. $out/${host.libdir}/${gccDir}
              chmod --recursive u+w "$out"
            ''
          else
            ""
        )
      ];

    unsafeDiscardReferences.out = true;

    system = build.system;
  };

  dereference-options =
    if host.name == "x86_64-w64-mingw32" then "--dereference --hard-dereference" else "";

  tarball = lib.bwrapDerivation {
    name = "${build.system}.${host.name}.andes.${target.name}.tarball";

    root = [ build.stdenv-nocc ];

    env = {
      inherit (build) PATH;
    };

    builder = lib.bashBuilder ''
      export XZ_OPT="--threads=''${NIX_BUILD_CORES} -9"
      mkdir --parents $out/
      tar --create --xz --verbose --owner=0 --group=0 --mode=u+w --transform="s,^./,${target.name}/,S" ${dereference-options} --file $out/${target.name}.tar.xz \
        --directory=${toolchain}/${host.prefix}/ . \
        --directory=${ide-gen-configs}/${host.prefix}/ . \
        --directory=${installer}/${host.prefix}/ .
    '';

    system = build.system;
  };

  apps =
    let
      mkApp =
        prog:
        toolchain
        // {
          outPath = "${toolchain}/${host.prefix}";
          meta.mainProgram = "${target.triple}-${prog}";
        };
    in
    {
      "ar" = mkApp "ar";
      "as" = mkApp "as";
      "clang" = mkApp "clang";
      "clang++" = mkApp "clang++";
      "cpp" = mkApp "cpp";
      "g++" = mkApp "g++";
      "gcc" = mkApp "gcc";
      "gcov" = mkApp "gcov";
      "ld" = mkApp "ld" // {
        "bfd" = mkApp "ld.bfd";
        "lld" = mkApp "ld.lld";
      };
      "nm" = mkApp "nm";
      "objcopy" = mkApp "objcopy";
      "objdump" = mkApp "objdump";
      "ranlib" = mkApp "ranlib";
      "readelf" = mkApp "readelf";
      "size" = mkApp "size";
      "strip" = mkApp "strip";
    };
in
toolchain
// {
  recurseForDerivations = true;

  inherit
    binutils
    gdb
    libc
    gcc-stage2
    llvm-project
    gcc-wrapper
    clang-wrapper
    ide-gen-configs
    installer
    ;

  ${if hasClangMultilibYaml then "clang-multilib-yaml" else null} = clang-multilib-yaml;

  ${if target.triple.os == "linux" then "libcxx" else null} = libcxx;
  ${if target.triple.os == "linux" then "compiler-rt-stage2" else null} = compiler-rt-stage2;

  ${if build.name == host.name then "gcc-stage1" else null} = gcc-stage1;

  ${if target.triple.os == "linux" then "linux-headers" else null} = linux-headers;

  inherit tarball;

  inherit
    sysroot
    target
    CROSS_COMPILE
    ;
}
// apps

